package com.pranit.productsupport.core.service;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;
@Service public class PaymentWebhookService {
 private final String secret;private final ObjectMapper mapper;private final PaymentTransactionService tx;
 public PaymentWebhookService(@Value("${app.payments.razorpay-webhook-secret:}") String secret,ObjectMapper mapper,PaymentTransactionService tx){this.secret=secret;this.mapper=mapper;this.tx=tx;}
 public void handle(byte[] body,String signature){if(secret==null||secret.isBlank())throw new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"Payment webhook secret is not configured");if(signature==null||!MessageDigest.isEqual(signature.getBytes(StandardCharsets.UTF_8),hmac(body).getBytes(StandardCharsets.UTF_8)))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid payment webhook signature");try{JsonNode root=mapper.readTree(body);String event=root.path("event").asText();if(!"order.paid".equals(event))return;JsonNode payload=root.path("payload");String orderId=payload.path("order").path("entity").path("id").asText("");String paymentId=payload.path("payment").path("entity").path("id").asText("");if(orderId.isBlank()||paymentId.isBlank())throw new ApiException(HttpStatus.BAD_REQUEST,"Webhook payload is missing order/payment IDs");tx.captureByOrder("RAZORPAY",orderId,paymentId);}catch(ApiException e){throw e;}catch(Exception e){throw new ApiException(HttpStatus.BAD_REQUEST,"Invalid payment webhook payload");}}
 private String hmac(byte[] body){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return java.util.HexFormat.of().formatHex(mac.doFinal(body));}catch(Exception e){throw new IllegalStateException("Cannot calculate webhook signature",e);}}
}
